#!/usr/bin/env python3
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
MAN=json.loads((ROOT/'release-manifest-v0.39.0.json').read_text())
REG=json.loads((ROOT/'registry/workspace-product-record-v0.39.0.json').read_text())
MAIN=(ROOT/'wordpress/sustainable-catalyst-workspace/sustainable-catalyst-workspace.php').read_text()
PHP=(ROOT/'wordpress/sustainable-catalyst-workspace/includes/class-sc-workspace.php').read_text()
REGPHP=(ROOT/'wordpress/sustainable-catalyst-workspace/includes/class-sc-workspace-registry.php').read_text()
JS=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/workspace-v0.39.0.js').read_text()
NB=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-research-notebook-v8.js').read_text()
REVIEW=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-notebook-review-provenance-v1.js').read_text()
PORT=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-notebook-portability-v1.js').read_text()
def c(x,l):
 if not x: raise SystemExit('FAIL - '+l)
 print('PASS - '+l)
c('Version: 0.39.0' in MAIN,'plugin version')
c((MAN['version'],MAN['previous_version'],MAN['release_name'])==('0.39.0','0.38.0','Notebook Review & Provenance'),'manifest release lineage')
c((MAN['storage_schema_version'],MAN['project_schema'],MAN['export_schema'])==(35,'sc-workspace-project/20.0','sc-workspace-project-export/20.0'),'storage 35 / project 20 / export 20')
c((MAN['migration']['storage_from'],MAN['migration']['storage_to'])==(34,35),'storage 34→35 migration')
c((MAN['migration']['project_schema_from'],MAN['migration']['project_schema_to'])==('sc-workspace-project/19.0','sc-workspace-project/20.0'),'project 19→20 migration')
c('function migrateV34(raw)' in JS and 'if (raw.schemaVersion === 34) return migrateV34(raw);' in JS,'browser migration runtime')
c(MAN['notebook_workspace_schema']=='sc-workspace-notebook-workspace/8.0' and MAN['notebook_export_schema']=='sc-workspace-notebook-export/8.0','Notebook Workspace/Export v8')
c("WORKSPACE_SCHEMA='sc-workspace-notebook-workspace/8.0'" in NB and 'governanceState' in NB and 'reviewProvenance' in NB,'Notebook v8 governance container')
c(all(x in REVIEW for x in ('buildReview','diff','hiddenChangeScore:false','reviewOnly:true','sourceStatesUnchanged:true')),'explicit Notebook Change Review')
c(all(x in REVIEW for x in ('buildReconciliation','applyReconciliation','newNotebookCopyOnly:true','preservesBothSourceStates:true')),'selective reconciliation preserves both source states')
c(all(x in REVIEW for x in ('auditEvents','lineage','shadowProvenanceDatabase:false','automaticInference:false','derivedFromAuthoritativeRecords:true')),'derived audit history and source lineage')
c(all(x in PHP for x in ('data-scw-notebook-review-create','data-scw-notebook-review-list','data-scw-notebook-reconcile-create','data-scw-notebook-lineage-inspect','data-scw-notebook-audit-list')),'Notebook Review & Provenance UI')
g=MAN['governance']
c(g['notebook_change_review_explicit'] and not g['notebook_change_review_hidden_score'],'review explicit / no hidden score')
c(g['notebook_reconciliation_explicit_selection_required'] and g['notebook_reconciliation_new_copy_only'],'reconciliation explicit and new-copy only')
c(g['notebook_audit_history_derived'] and not g['notebook_audit_shadow_database'],'audit derived / no shadow provenance database')
c(not g['notebook_lineage_automatic_inference'],'no automatic lineage inference')
c(all(x in PORT for x in ('expectedRevision','revision-precondition','silentLastWriteWins:false')),'v0.38 conflict-safe sync retained')
c(not MAN['governance']['notebook_background_sync'] and not MAN['governance']['notebook_silent_last_write_wins'],'no background sync / no last-write-wins retained')
c((REG['public_version'],REG['previous_version'])==('0.39.0','0.38.0'),'registry lineage')
c("BACKUP_KEY = 'sc_workspace_registry_backup_v0390'" in REGPHP and 'LEGACY_PENDING_KEY_V0380' in REGPHP,'registry retry lineage')
c((ROOT/'history/release-manifest-v0.38.0.json').exists() and (ROOT/'history/workspace-product-record-v0.38.0.json').exists(),'v0.38 history preserved')
for p in list((ROOT/'schemas').glob('*.json'))+[ROOT/'release-manifest-v0.39.0.json',ROOT/'registry/workspace-product-record-v0.39.0.json']:
 json.loads(p.read_text())
print('VALIDATION PASSED: Sustainable Catalyst Workspace v0.39.0 — Notebook Review & Provenance')
